SELECT
ROW_NUMBER() OVER (
ORDER BY SUM(curr.amount) DESC
) AS category_id,

curr.category AS category_code,
SUM(curr.amount) AS amount,




CAST(10 AS SIGNED) AS comparison_rate,

CAST(
ROUND(
SUM(curr.amount) * 100.0
/ NULLIF(total.total_amount, 0)
) AS SIGNED
) AS expense_rate

FROM service_record curr

CROSS JOIN (
SELECT SUM(amount) AS total_amount
FROM service_record
WHERE user_id = #{userId}
AND type = 'EXPENSE'
AND YEAR(record_date) = #{year}
AND MONTH(record_date) = #{month}
) total



WHERE curr.user_id = #{userId}
AND curr.type = 'EXPENSE'
AND YEAR(curr.record_date) = #{year}
AND MONTH(curr.record_date) = #{month}

GROUP BY
curr.category,
total.total_amount



ORDER BY SUM(curr.amount) DESC

SELECT
    COALESCE(changed_category, category) AS categoryCode,
    SUM(amount) AS amount
FROM service_record
WHERE user_id = #{userId}
  AND type = 'EXPENSE'
  AND YEAR(record_date) = #{year}
  AND MONTH(record_date) = #{month}
GROUP BY COALESCE(changed_category, category)
ORDER BY amount DESC

SELECT ef.id AS feedbackId, ef.writer_id AS writerUserId, u.name AS writerName, ef.receiver_id AS receiverId, ef.content AS content FROM expense_feedback ef INNER JOIN user u ON u.id = ef.writer_id WHERE ef.year = #{year} AND ef.month = #{month} AND ( (ef.writer_id = #{userId} OR ef.receiver_id = #{userId})
OR (ef.writer_id = #{partnerId} OR ef.receiver_id = #{partnerId})
) ORDER BY ef.id ASC

